//! Cargo-driven `netsh.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is netsh-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");

    // The C left, and its part of cmake's C rule; reactos-link adds what every C
    // compile shares from reactos-link/cflags/c.<arch>.flags (Linker::c_compiled).
    let c_sources: &[&str] = &["base/applications/network/netsh/rust_varargs_shim.c"];
    let c_includes: &[&str] = &[
        "@build/base/applications/network/netsh",
        "base/applications/network/netsh",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/conutils",
    ];
    let c_flags: &[&str] = match arch.as_str() {
        "x86" => &[
            "-isystem",
            "{REPO}/sdk/lib/pseh/include",
            "-isystem",
            "{REPO}/sdk/lib/tdilib",
            "-isystem",
            "{REPO}/vendor/zlib/include",
            "-isystem",
            "{REPO}/vendor/libtiff/include",
            "-isystem",
            "{REPO}/vendor/symcrypt/inc",
            "-isystem",
            "{REPO}/vendor/symcrypt/lib",
            "-std=gnu99",
            "@core",
        ],
        "x86_64" => &[
            "-isystem",
            "{REPO}/sdk/lib/pseh/include",
            "-isystem",
            "{REPO}/sdk/lib/tdilib",
            "-isystem",
            "{REPO}/vendor/zlib/include",
            "-isystem",
            "{REPO}/vendor/libtiff/include",
            "-isystem",
            "{REPO}/vendor/symcrypt/inc",
            "-isystem",
            "{REPO}/vendor/symcrypt/lib",
            "-std=gnu99",
            "-U_X86_",
            "-UWIN32",
            "@core",
        ],
        "aarch64" => &[
            "-isystem",
            "{REPO}/sdk/lib/pseh/include",
            "-isystem",
            "{REPO}/sdk/lib/tdilib",
            "-isystem",
            "{REPO}/vendor/zlib/include",
            "-isystem",
            "{REPO}/vendor/libtiff/include",
            "-isystem",
            "{REPO}/vendor/symcrypt/inc",
            "-isystem",
            "{REPO}/vendor/symcrypt/lib",
            "-std=gnu99",
            "@core",
        ],
        _ => unreachable!(),
    };
    let c_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_UNICODE",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/base/applications/network/netsh",
        "base/applications/network/netsh",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["UNICODE", "WINVER=0x502", "_UNICODE", "_WIN32_WINNT=0x502"];

    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_wmainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "wmainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "wmainCRTStartup"),
        o => panic!("netsh-cargo: unsupported arch {o}"),
    };

    let late_libs: &[&str] = match arch.as_str() {
        "x86" => &["engine:conutils", "engine:oldnames", "engine:pseh", "engine:chkstk", "engine:conutils_rust"],
        "x86_64" => &["engine:conutils", "engine:oldnames", "engine:pseh", "engine:conutils_rust"],
        "aarch64" => &["engine:conutils", "engine:oldnames", "engine:pseh", "engine:chkstk", "engine:conutils_rust"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("netsh-rust")
        .c_compiled("netsh_shims", c_sources, c_includes, c_flags, c_defines)
        .rc("base/applications/network/netsh/netsh.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("base/applications/network/netsh/netsh.spec", "netsh.exe")
        .spec_stubs()
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/iphlpapi/iphlpapi.spec", "iphlpapi.dll", "iphlpapi")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // ...and those cmake linked after the body, in the same order.
        .static_libs_after_body(late_libs)
        .msvcrtex_crt(MsvcrtexKind::ExeWide)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "console:5.01".into(),
        });
}
